record.field:
batch = env['stock.picking.batch'].browse(record.res_id)
missing_lot_filter = env.ref( 'fmcg_business_automation.' 'ir_filter_stock_picking_missing_lot_serial' )
missing_lot_pickings = batch.picking_ids.filtered_domain( missing_lot_filter._get_eval_domain() )
validate_activity_type = env.ref( 'fmcg_business_automation.' 'mail_activity_type_validate_assigned_picking' ) fill_lot_activity_type = env.ref( 'fmcg_business_automation.' 'mail_activity_type_picking_fill_missing_lot_serial' ) assign_lot_activity_type = env.ref( 'fmcg_business_automation.' 'mail_activity_type_picking_assign_existing_lot_serial' )
lot_activity_type_ids = [ validate_activity_type.id, fill_lot_activity_type.id, assign_lot_activity_type.id, ]
if missing_lot_pickings: for picking in missing_lot_pickings: activities = env['mail.activity'].search([ ('active', '=', True), ('res_model', '=', 'stock.picking'), ('res_id', '=', picking.id), ('activity_type_id', 'in', lot_activity_type_ids), ], order='create_date asc, id asc')
if activities: activities.action_feedback() else: picking.activity_schedule( activity_type_id=fill_lot_activity_type.id, summary='Fill missing Lot/Serial', user_id=record.user_id.id, )
# Batch chưa đủ điều kiện Validate. # Mở lại activity để lần chạy sau kiểm tra lại. record.write({ 'active': True, 'feedback': False, })
else: batch.action_done() batch._compute_state()
batch.message_post( body=( 'Batch transfer was validated automatically after ' 'all child pickings had complete Lot/Serial information.' ), message_type='comment', subtype_xmlid='mail.mt_note', )
